page_settings.custom_css:
/*حذف جمع جزئ*/
.cart-subtotal{display:none;}
/*سبد خرید*/
.elementor-widget-woocommerce-cart .woocommerce table.shop_table .product-remove a{color:transparent!important;
	background-image:url(https://saipalahijan.com/wp-content/uploads/2024/01/Frame-8-3.svg);
	background-position:center;
	background-size:contain;
	background-repeat:no-repeat;
	width:40px}
.product-thumbnail{display:block!important;}
.product-thumbnail img{border-radius:10px}
.woocommerce .product-thumbnail:before{display:none;}
/*قبل از تایتل*/
.nias-tiltebefore:before{content: "";
    background-color: #f47421;
    width: 100%;
    height: 10px;
    position: absolute;
    bottom: -10px;
    border-radius: 10px 10px 0 0}
.nias-tiltebefore:after{content: "";
    top: 20px;
    width: 100%;
    height: 0px;
    position: absolute;
    box-shadow: 0 0 70px 10px #f47421;
z-index: -1;}
/*فونت قیمت*/
span.woocommerce-Price-amount.amount{font-size: 20px!important;
    font-weight: bold;}
.price del span.woocommerce-Price-amount.amount{font-size:17px!important;
	font-weight:normal;}
.quantity{margin:0!important;
	  width: 115px;
    display: flex;
    justify-content: center;
    align-items: center;}
/*لوپ محصولات نیاس*/
.niaslooptitle{overflow:hidden;}
.niaslooptitle a{overflow: hidden;
    text-align: center;
    text-overflow: ellipsis;
    white-space: nowrap;
    width: 100%;}
.niasmainbox:hover .nias-addtocart , .niasmainbox:hover .nias-preview{opacity: 1;
    visibility: visible;
    height:max-content;
    transition:0.5s;}
/*کد های سرچ نیاس*/
.nias-search-icon , .nias-search-close{cursor:pointer;}
.nias-search-form-inner{display: flex;
    gap: 20px;}
.nias-search-button , .nias-search-select , .nias-search-input{border: none!important;
    outline: none!important;
    border-radius: 10px!important;}
.nias-search-select{width: 150px;}
.nias-search-content{position:fixed;
	z-index:999;
	top:0;
	right:0;
	height:100vh;
	background-color:#bdbcbceb;
border-radius:50%;
	transform:scale(0);
	transition:all 0.3s linear;
	opacity:0;}
.nias-search-content.active{transform:scale(1);
	border-radius:0;
	opacity:1;}
.nias-search-form-inner input{padding:12px;
	font-family: "nias Peyda";}
.product-nias-result-content{max-height: 400px;
    overflow-y: scroll;}
.nias-search-select{font-family: "nias Peyda";}
/*حل مشکل لوپ کروسل*/
.nias-loop .swiper.elementor-loop-container{overflow-y: visible;
    height: 545px;}
body:not(.rtl) .elementor-element.elementor-element-139f60b .elementor-icon-list-text{padding-left:5px;}
body.rtl .elementor-element.elementor-element-139f60b .elementor-icon-list-text{padding-right:5px;}
body.rtl .elementor-element.elementor-element-8ddd131 .elementor-icon-list-items.elementor-inline-items .elementor-icon-list-item:after{left:calc(-50px/2);}
body:not(.rtl) .elementor-element.elementor-element-8ddd131 .elementor-icon-list-items.elementor-inline-items .elementor-icon-list-item:after{right:calc(-50px/2);}
